import re, glob, os, statistics as st

S = os.path.dirname(os.path.abspath(__file__))

def parse_py(path):
    losses, samples = {}, []
    for line in open(path):
        m = re.match(r'step\s+(\d+) /\s+\d+ \| loss ([\d.]+)', line)
        if m: losses[int(m.group(1))] = float(m.group(2))
        m = re.match(r'sample\s+\d+: (.*)', line)
        if m: samples.append(m.group(1).strip())
    return losses, samples

def parse_fs(path):
    losses, samples = {}, []
    for line in open(path):
        m = re.match(r'step (\d+) / \d+\s+loss ([-\d.eE]+)\s+elapsed (\d+) ms', line)
        if m: losses[int(m.group(1))] = float(m.group(2))
        m = re.match(r'sample (\d+): (.*)', line)
        if m: samples.append(m.group(2).strip())
    return losses, samples

runs = []
for f in sorted(glob.glob(S + '/fortress_run*.log')):
    l, s = parse_fs(f)
    if l: runs.append(('FS-' + re.search(r'run(\d)', f).group(1), l, s))
pys = []
for f in sorted(glob.glob(S + '/py_seed*.log'), key=lambda p: int(re.search(r'seed(\d+)', p).group(1))):
    l, s = parse_py(f)
    if len(l) == 25: pys.append(('py' + re.search(r'seed(\d+)', f).group(1), l, s))

steps = list(range(10, 251, 10))
cols = runs + pys
print('| step | ' + ' | '.join(n for n, _, _ in cols) + ' |')
print('|---' * (len(cols) + 1) + '|')
for k in steps:
    print(f'| {k} | ' + ' | '.join(f'{d.get(k, float("nan")):.4f}' for _, d, _ in cols) + ' |')

def stats(d):
    v = [d[k] for k in steps if k in d]
    last = [d[k] for k in steps[-10:] if k in d]
    return st.mean(v), st.mean(last), min(v), max(v)

print()
print('| run | mean(all 25) | mean(last 10: steps 160-250) | min | max | final(250) |')
print('|---|---|---|---|---|---|')
for n, d, _ in cols:
    a, b, lo, hi = stats(d)
    print(f'| {n} | {a:.4f} | {b:.4f} | {lo:.4f} | {hi:.4f} | {d.get(250, float("nan")):.4f} |')

print()
pyv = [stats(d)[1] for _, d, _ in pys]
if pyv:
    print(f'python cross-seed mean(last10): mean {st.mean(pyv):.4f} sd {st.pstdev(pyv):.4f} range [{min(pyv):.4f}, {max(pyv):.4f}] over n={len(pyv)}')
fsv = [stats(d)[1] for _, d, _ in runs]
if fsv:
    print('fortress mean(last10): ' + ', '.join(f'{x:.4f}' for x in fsv))

print()
for n, _, s in cols:
    print(f'{n} samples: ' + ', '.join(s))

